import {
  createProxyMiddleware,
  Options,
  responseInterceptor,
  fixRequestBody,
} from 'http-proxy-middleware';
import type { IncomingMessage, ServerResponse, ClientRequest } from 'http';
import type { NextFunction } from 'express';
import { randomBytes } from 'crypto';
import { createLogger } from '../utils/logger';
import { renderRivetPage } from '../utils/rivetPage';
import { Socket } from 'net';
import {
  insertHtmlHeadElements,
  type HeadElement,
} from '../utils/htmlDocument';
import {
  createPreviewConnectionsScript,
  PREVIEW_CONNECTIONS_SCRIPT_ID,
} from './preview-connections';
import {
  allowPreviewBridgeNonceInCsp,
  createPreviewBridgeScript,
  injectPreviewBridge,
  isHtmlDocumentRequest,
  PREVIEW_BRIDGE_SCRIPT_ID,
  shouldInjectPreviewBridge,
} from './preview-bridge';

const log = createLogger('ProxyConfig');

const PROXY_LIBRARY_PLACEHOLDER_TARGET = 'http://127.0.0.1:9';
const TARGET_ADDRESSED_PREVIEW_PREFIX = '/__rivet/preview';
const TARGET_ADDRESSED_PREVIEW_KIND_BASE = 'base';
const TARGET_ADDRESSED_PREVIEW_KIND_HISTORY = 'history';
const TARGET_ADDRESSED_PREVIEW_KIND_VARIANT = 'variant';
const CACHE_VALIDATOR_REQUEST_HEADERS = [
  'if-none-match',
  'if-modified-since',
] as const;

const hasValidUserDevPort = (userPort: number): boolean =>
  Number.isInteger(userPort) && userPort > 0;

type TargetAddressedPreview = {
  upstream: string | null;
  path: string;
  previewPrefix?: string;
};

type ResolvedProxyTarget = {
  upstream: string | null;
  path: string;
  isTargetAddressed: boolean;
  previewPrefix?: string;
  redirectTo?: string;
};

type VariantPreviewSource = 'history' | 'live';

type ResolveVariantPreviewPort = (
  sessionId: string,
  variantId: string,
  options?: { source: VariantPreviewSource },
) => number | null;

export const resolveTargetAddressedPreview = (args: {
  rawUrl: string | undefined;
  defaultTarget: string | null;
  resolveVariantPreviewPort?: ResolveVariantPreviewPort;
}): TargetAddressedPreview | null => {
  const parsed = new URL(args.rawUrl ?? '/', 'http://rivet.local');
  if (!parsed.pathname.startsWith(TARGET_ADDRESSED_PREVIEW_PREFIX + '/'))
    return null;
  const segments = parsed.pathname.split('/');
  const kind = segments[3];
  if (kind === TARGET_ADDRESSED_PREVIEW_KIND_BASE) {
    const previewPrefix = TARGET_ADDRESSED_PREVIEW_PREFIX + '/' + kind;
    return {
      upstream: args.defaultTarget,
      path:
        (parsed.pathname.slice(previewPrefix.length) || '/') + parsed.search,
      previewPrefix,
    };
  }
  const isHistoryPreview = kind === TARGET_ADDRESSED_PREVIEW_KIND_HISTORY;
  if (kind !== TARGET_ADDRESSED_PREVIEW_KIND_VARIANT && !isHistoryPreview)
    return null;
  const sessionId = segments[4];
  const variantId = segments[5];
  if (!sessionId || !variantId) return { upstream: null, path: '/' };
  const previewPrefix = segments.slice(0, 6).join('/');
  const port =
    args.resolveVariantPreviewPort?.(sessionId, variantId, {
      source: isHistoryPreview ? 'history' : 'live',
    }) ?? null;
  const upstream =
    port !== null && Number.isInteger(port) && port > 0
      ? 'http://localhost:' + port
      : null;
  return {
    upstream,
    path: (parsed.pathname.slice(previewPrefix.length) || '/') + parsed.search,
    previewPrefix,
  };
};

const getRefererPreviewPath = (req: IncomingMessage): string | null => {
  const rawReferer = req.headers.referer ?? req.headers.referrer;
  if (typeof rawReferer !== 'string') return null;
  try {
    const parsed = new URL(rawReferer);
    return `${parsed.pathname}${parsed.search}`;
  } catch {
    return null;
  }
};

const shouldRedirectToTargetAddress = (req: IncomingMessage): boolean => {
  const method = req.method ?? 'GET';
  return method === 'GET' || method === 'HEAD';
};

const appendRequestPath = (
  prefix: string,
  rawUrl: string | undefined,
): string =>
  `${prefix}${rawUrl?.startsWith('/') ? rawUrl : `/${rawUrl ?? ''}`}`;

export const markPreviewBridgeDocumentUncacheable = (
  proxyRes: IncomingMessage,
): void => {
  proxyRes.headers['cache-control'] = 'no-cache, no-store';
};

export const createUserDevServerProxy = (
  userPort: number,
  userHost: string = 'localhost',
  options: {
    isPreviewBridgeEnabled?: boolean;
    expectedPreviewParentOrigin?: string;
    resolveVariantPreviewPort?: ResolveVariantPreviewPort;
  } = {},
) => {
  let variantTarget: string | null = null;
  const requestTargets = new WeakMap<IncomingMessage, ResolvedProxyTarget>();
  const hasDefaultUpstream = hasValidUserDevPort(userPort);
  const isPreviewBridgeEnabled = options.isPreviewBridgeEnabled ?? false;
  const defaultTarget = hasDefaultUpstream
    ? `http://${userHost}:${userPort}`
    : null;

  const getActiveUpstream = (): string | null =>
    variantTarget ?? defaultTarget ?? null;

  const getResolvedProxyTarget = (
    req: IncomingMessage,
  ): ResolvedProxyTarget => {
    const existing = requestTargets.get(req);
    if (existing) return existing;
    const targetAddressedPreview = resolveTargetAddressedPreview({
      rawUrl: req.url,
      defaultTarget,
      resolveVariantPreviewPort: options.resolveVariantPreviewPort,
    });
    if (targetAddressedPreview) {
      return {
        ...targetAddressedPreview,
        isTargetAddressed: true,
      };
    }
    const refererPreviewPath = getRefererPreviewPath(req);
    const refererTarget = resolveTargetAddressedPreview({
      rawUrl: refererPreviewPath ?? undefined,
      defaultTarget,
      resolveVariantPreviewPort: options.resolveVariantPreviewPort,
    });
    if (refererTarget) {
      const { previewPrefix } = refererTarget;
      return {
        upstream: refererTarget.upstream,
        path: req.url ?? '/',
        isTargetAddressed: false,
        previewPrefix,
        redirectTo:
          previewPrefix && shouldRedirectToTargetAddress(req)
            ? appendRequestPath(previewPrefix, req.url)
            : undefined,
      };
    }
    return {
      upstream: getActiveUpstream(),
      path: req.url ?? '/',
      isTargetAddressed: false,
    };
  };

  const bindRequestTarget = (
    req: IncomingMessage,
    target: ResolvedProxyTarget,
  ): void => {
    requestTargets.set(req, target);
    if (target.isTargetAddressed) {
      req.url = target.path;
      for (const header of CACHE_VALIDATOR_REQUEST_HEADERS) {
        delete req.headers[header];
      }
    }
  };

  const getRouterTargetForLibrary = (req?: IncomingMessage): string => {
    if (req) {
      return (
        getResolvedProxyTarget(req).upstream ?? PROXY_LIBRARY_PLACEHOLDER_TARGET
      );
    }
    return getActiveUpstream() ?? PROXY_LIBRARY_PLACEHOLDER_TARGET;
  };

  const getActiveTargetPort = (): number | string => {
    const active = getActiveUpstream();
    if (!active) {
      return hasDefaultUpstream ? userPort : 'not configured';
    }
    try {
      const parsed = new URL(active);
      const parsedPort = Number(parsed.port);
      if (Number.isInteger(parsedPort) && parsedPort > 0) {
        return parsedPort;
      }
    } catch {}
    return userPort > 0 ? userPort : 'not configured';
  };

  const setVariantTarget = (port: number | null) => {
    const prior = variantTarget ?? defaultTarget ?? '(none)';
    const next =
      port !== null && Number.isInteger(port) && port > 0
        ? `http://localhost:${port}`
        : null;
    variantTarget = next;
    const nextLabel = next ?? defaultTarget ?? '(none)';
    log.info(`setVariantTarget: ${prior} → ${nextLabel}`);
  };

  const prepareProxyResponseHeaders = (proxyRes: IncomingMessage) => {
    delete proxyRes.headers['x-frame-options'];
    delete proxyRes.headers['content-security-policy-report-only'];

    if (proxyRes.headers['content-security-policy']) {
      const csp = proxyRes.headers['content-security-policy'];
      if (typeof csp === 'string') {
        proxyRes.headers['content-security-policy'] = csp.replace(
          /frame-ancestors[^;]*;?/,
          '',
        );
      }
    }
  };

  const allowPreviewScriptInCsp = (
    proxyRes: IncomingMessage,
    scriptNonce: string,
  ) => {
    const csp = proxyRes.headers['content-security-policy'];
    if (typeof csp === 'string') {
      proxyRes.headers['content-security-policy'] =
        allowPreviewBridgeNonceInCsp(csp, { scriptNonce });
      return;
    }
    if (Array.isArray(csp)) {
      proxyRes.headers['content-security-policy'] = csp.map((value) =>
        allowPreviewBridgeNonceInCsp(value, { scriptNonce }),
      );
    }
  };

  const handleHtmlProxyResponse = (
    proxyRes: IncomingMessage,
    req: IncomingMessage,
    res: ServerResponse,
  ): void => {
    prepareProxyResponseHeaders(proxyRes);
    const contentType = proxyRes.headers['content-type'];
    const isPreviewDocument = shouldInjectPreviewBridge({
      method: req.method,
      accept: req.headers.accept,
      contentType,
    });
    const previewPrefix = requestTargets.get(req)?.previewPrefix;
    const scriptNonce = isPreviewDocument
      ? randomBytes(16).toString('base64')
      : null;
    if (scriptNonce) {
      allowPreviewScriptInCsp(proxyRes, scriptNonce);
      markPreviewBridgeDocumentUncacheable(proxyRes);
    }

    const interceptResponse = responseInterceptor(async (responseBuffer) => {
      if (!scriptNonce) {
        return responseBuffer;
      }
      const scripts: HeadElement[] = [];
      if (isPreviewBridgeEnabled) {
        scripts.push({
          tagName: 'script',
          id: PREVIEW_BRIDGE_SCRIPT_ID,
          markup: createPreviewBridgeScript({
            expectedParentOrigin: options.expectedPreviewParentOrigin,
            scriptNonce,
          }),
        });
      }
      if (previewPrefix) {
        scripts.push({
          tagName: 'script',
          id: PREVIEW_CONNECTIONS_SCRIPT_ID,
          markup: createPreviewConnectionsScript({
            previewPrefix,
            scriptNonce,
          }),
        });
      }
      return insertHtmlHeadElements(responseBuffer.toString('utf8'), scripts);
    });
    void interceptResponse(proxyRes, req, res);
  };

  const createProxyOptions = (isHtmlTransformProxy: boolean): Options => ({
    target: defaultTarget ?? PROXY_LIBRARY_PLACEHOLDER_TARGET,
    router: (req) => getRouterTargetForLibrary(req as IncomingMessage),
    changeOrigin: true,
    selfHandleResponse: isHtmlTransformProxy,
    on: {
      proxyRes: isHtmlTransformProxy
        ? handleHtmlProxyResponse
        : (
            proxyRes: IncomingMessage,
            _req: IncomingMessage,
            _res: ServerResponse,
          ) => {
            prepareProxyResponseHeaders(proxyRes);
          },
      proxyReq: (
        proxyReq: ClientRequest,
        req: IncomingMessage,
        _res: ServerResponse,
      ) => {
        if (req.headers.host) {
          proxyReq.setHeader('x-forwarded-host', req.headers.host);
        }
        fixRequestBody(proxyReq, req);

        const originalPath = req.url;
        const proxiedPath = proxyReq.path;
        log.debug(
          `Proxying ${req.method} ${originalPath} -> ${proxiedPath} to ${getRouterTargetForLibrary(req)}`,
        );
      },
      error: (
        err: Error,
        req: IncomingMessage,
        res: ServerResponse<IncomingMessage> | Socket,
      ) => {
        log.warn(`Proxy error for ${req.method} ${req.url}:`, err.message);
        if (res && 'writeHead' in res && !res.headersSent) {
          res.writeHead(502, { 'Content-Type': 'application/json' });
          res.end(
            JSON.stringify({
              error: 'Proxy Error',
              message: `Failed to connect to development server on port ${getActiveTargetPort()}`,
              details: err.message,
            }),
          );
        }
      },
    },
    ws: !isHtmlTransformProxy,
    proxyTimeout: 30_000,
    timeout: 30_000,
  });

  const proxyMiddlewareInstance = createProxyMiddleware(
    createProxyOptions(false),
  );
  const htmlTransformProxyMiddlewareInstance = createProxyMiddleware(
    createProxyOptions(true),
  );
  type ProxyMiddlewareInstanceType = typeof proxyMiddlewareInstance;

  const gatedHttp = (
    req: IncomingMessage,
    res: ServerResponse,
    next: NextFunction,
  ): void => {
    const target = getResolvedProxyTarget(req);
    bindRequestTarget(req, target);
    if (target.redirectTo) {
      res.writeHead(307, {
        Location: target.redirectTo,
        'Cache-Control': 'no-cache, no-store',
      });
      res.end();
      return;
    }
    const upstream = target.upstream;
    if (upstream === null) {
      if ('writeHead' in res && !res.headersSent) {
        if (isPreviewBridgeEnabled && isHtmlDocumentRequest(req)) {
          log.debug(
            `Serving preview holding page — no upstream yet (userPort=${userPort}).`,
          );
          const body = injectPreviewBridge(
            renderRivetPage({
              page: { kind: 'preview-waiting' },
              head: { title: 'Preview — waiting for dev server' },
            }),
            { expectedParentOrigin: options.expectedPreviewParentOrigin },
          );
          res.writeHead(200, {
            'Content-Type': 'text/html; charset=utf-8',
            'Cache-Control': 'no-cache, no-store',
          });
          res.end(body);
          return;
        }
        log.debug(
          `Rejecting proxied preview request — no upstream (userPort=${userPort}).`,
        );
        res.writeHead(503, { 'Content-Type': 'application/json' });
        res.end(
          JSON.stringify({
            error: 'Preview unavailable',
            message:
              'No upstream development server yet. Variant previews will reconnect automatically when ready.',
          }),
        );
      }
      return;
    }
    const middleware =
      (isPreviewBridgeEnabled || target.previewPrefix) &&
      isHtmlDocumentRequest(req)
        ? htmlTransformProxyMiddlewareInstance
        : proxyMiddlewareInstance;
    void middleware(req, res, next);
  };

  const gated = gatedHttp as ProxyMiddlewareInstanceType;
  gated.upgrade = (
    req: IncomingMessage,
    socket: Socket,
    head: Buffer,
  ): void => {
    const target = getResolvedProxyTarget(req);
    bindRequestTarget(req, target);
    if (target.upstream === null) {
      log.debug(
        `Rejecting WebSocket upgrade — no upstream (userPort=${userPort}).`,
      );
      socket.destroy();
      return;
    }
    if (proxyMiddlewareInstance.upgrade) {
      proxyMiddlewareInstance.upgrade(req, socket, head);
      return;
    }
    socket.destroy();
  };

  if (hasDefaultUpstream) {
    log.info(`Created proxy middleware → default ${userHost}:${userPort}`);
  } else {
    log.info(
      `Created proxy middleware → no default user dev port (${userPort}); variant preview must set upstream`,
    );
  }

  return { middleware: gated, setVariantTarget };
};
